"use client";

import { useState } from "react";
import { PillToggle } from "@/components/ui/pill-toggle";
import { CostMetrics } from "@/components/dashboard/cost-metrics";
import { Charts } from "@/components/dashboard/charts";
import { SystemLogs } from "@/components/dashboard/system-logs";
import { Footer } from "@/components/dashboard/footer";
import { Sidebar } from "@/components/jobs/sidebar";
import { JobDetail } from "@/components/jobs/job-detail";
import {
  ChevronDownIcon,
  LinkIcon,
} from "@heroicons/react/20/solid";

const views = [
  { label: "Dashboard", value: "dashboard" },
  { label: "Jobs", value: "jobs" },
];

export default function Home() {
  const [view, setView] = useState("dashboard");
  const [selectedJobId, setSelectedJobId] = useState<string | null>("1");

  return (
    <div className="flex flex-col min-h-screen">
      {/* ── Top Bar ───────────────────────────────────────────────────────── */}
      <header className="flex items-center px-5 py-3 border-b border-border bg-surface/60 backdrop-blur-sm">
        {/* Instance switcher (left) */}
        <button className="flex items-center gap-1.5 text-sm text-text-secondary hover:text-text-primary transition-colors cursor-pointer">
          <LinkIcon className="h-3.5 w-3.5 text-primary" />
          <span className="font-medium">Local</span>
          <ChevronDownIcon className="h-4 w-4 opacity-50" />
        </button>

        {/* Centered pill toggle */}
        <div className="flex-1 flex justify-center">
          <PillToggle value={view} onChange={setView} options={views} />
        </div>

        {/* Right spacer to balance the layout */}
        <div className="w-[90px]" />
      </header>

      {/* ── Content ───────────────────────────────────────────────────────── */}
      {view === "dashboard" ? (
        <DashboardView />
      ) : (
        <JobsView
          selectedJobId={selectedJobId}
          onSelectJob={setSelectedJobId}
        />
      )}
    </div>
  );
}

/* ── Dashboard View ────────────────────────────────────────────────────── */
function DashboardView() {
  return (
    <div className="flex flex-col flex-1">
      <main className="flex-1 mx-auto w-full max-w-6xl px-6 py-6 space-y-5">
        <CostMetrics />
        <Charts />
        <div className="flex-1 min-h-[320px]">
          <SystemLogs />
        </div>
      </main>
      <Footer />
    </div>
  );
}

/* ── Jobs View ─────────────────────────────────────────────────────────── */
function JobsView({
  selectedJobId,
  onSelectJob,
}: {
  selectedJobId: string | null;
  onSelectJob: (id: string) => void;
}) {
  return (
    <div className="flex flex-1 overflow-hidden">
      <Sidebar selectedJobId={selectedJobId} onSelectJob={onSelectJob} />
      {selectedJobId ? (
        <JobDetail jobId={selectedJobId} />
      ) : (
        <div className="flex-1 flex items-center justify-center text-text-secondary text-sm">
          Select a job to view details
        </div>
      )}
    </div>
  );
}
