"use client";

import { cn } from "@/lib/utils";
import { jobs, runs, type Job, type JobStatus } from "@/lib/mock-data";
import { Button } from "@/components/ui/button";
import { PlusIcon } from "@heroicons/react/20/solid";

const statusDot: Record<JobStatus, string> = {
  ok: "bg-success",
  failed: "bg-error",
  running: "bg-info",
  disabled: "bg-text-secondary/40",
};

interface SidebarProps {
  selectedJobId: string | null;
  onSelectJob: (id: string) => void;
}

export function Sidebar({ selectedJobId, onSelectJob }: SidebarProps) {
  // Group recent runs by job
  const recentByJob = runs.reduce(
    (acc, run) => {
      if (!acc[run.jobName]) acc[run.jobName] = [];
      if (acc[run.jobName].length < 3) acc[run.jobName].push(run);
      return acc;
    },
    {} as Record<string, typeof runs>
  );

  return (
    <aside className="flex w-64 flex-col border-r border-border bg-surface overflow-hidden">
      {/* Header + Create */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-border">
        <h2 className="text-xs font-semibold uppercase tracking-wider text-text-secondary">
          Jobs
        </h2>
        <Button variant="primary" size="sm" className="h-7 text-xs gap-1">
          <PlusIcon className="h-3.5 w-3.5" />
          Create
        </Button>
      </div>

      {/* Job list */}
      <nav className="flex-1 overflow-y-auto py-1">
        {jobs.map((job) => (
          <button
            key={job.id}
            onClick={() => onSelectJob(job.id)}
            className={cn(
              "w-full flex items-center gap-3 px-4 py-2.5 text-left transition-colors cursor-pointer",
              selectedJobId === job.id
                ? "bg-surface-elevated"
                : "hover:bg-surface-elevated/50"
            )}
          >
            {/* Status dot */}
            <span
              className={cn(
                "h-2 w-2 rounded-full flex-shrink-0",
                statusDot[job.status],
                job.status === "running" && "animate-pulse"
              )}
            />
            <div className="min-w-0 flex-1">
              <p
                className={cn(
                  "text-sm font-medium truncate",
                  selectedJobId === job.id
                    ? "text-text-primary"
                    : "text-text-primary/80"
                )}
              >
                {job.name}
              </p>
              <p className="text-[11px] font-mono text-text-secondary/60 truncate">
                {job.schedule}
              </p>
            </div>
          </button>
        ))}
      </nav>

      {/* Recent Runs */}
      <div className="border-t border-border">
        <div className="px-4 py-2.5">
          <h3 className="text-[10px] font-semibold uppercase tracking-wider text-text-secondary/60">
            Recent Runs
          </h3>
        </div>
        <div className="overflow-y-auto max-h-48 pb-2">
          {Object.entries(recentByJob).map(([jobName, jobRuns]) => (
            <div key={jobName} className="px-4 mb-2">
              <p className="text-[11px] font-medium text-text-secondary mb-1">
                {jobName}
              </p>
              {jobRuns.map((run) => (
                <div
                  key={run.id}
                  className="flex items-center gap-2 py-0.5 text-[10px]"
                >
                  <span
                    className={cn(
                      "h-1.5 w-1.5 rounded-full flex-shrink-0",
                      run.status === "success" && "bg-success",
                      run.status === "failed" && "bg-error",
                      run.status === "running" && "bg-info animate-pulse",
                      run.status === "killed" && "bg-warning"
                    )}
                  />
                  <span className="font-mono text-text-secondary/60 truncate">
                    {run.started.split(" ")[1]}
                  </span>
                  <span className="font-mono text-text-secondary/40 ml-auto">
                    {run.duration}
                  </span>
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>
    </aside>
  );
}
