"use client";

import { metrics } from "@/lib/mock-data";

interface MetricCardProps {
  label: string;
  value: string;
  sub?: string;
}

function MetricCard({ label, value, sub }: MetricCardProps) {
  return (
    <div className="rounded-lg border border-border bg-surface px-5 py-4">
      <p className="text-2xl font-semibold tracking-tight text-text-primary">
        {value}
      </p>
      <p className="mt-1 text-xs font-medium text-text-secondary">{label}</p>
      {sub && (
        <p className="mt-0.5 text-[10px] text-text-secondary/60">{sub}</p>
      )}
    </div>
  );
}

export function CostMetrics() {
  return (
    <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
      <MetricCard label="Total Cost" value={metrics.totalCost} sub="All time" />
      <MetricCard label="Today's Cost" value={metrics.todayCost} sub="Apr 18" />
      <MetricCard label="Total Runs" value={metrics.totalRuns} sub="All time" />
      <MetricCard label="Active Jobs" value={metrics.activeJobs} sub="Enabled" />
    </div>
  );
}
